    """Returns a divisor-count based value: divisors of the odd part, or a small power-of-two special case."""
    def count_divisors(n: int) -> int:
        if n <= 0:
            return 0
        ans = 1
        d = 2
        while d * d <= n:
            if n % d == 0:
                e = 0
                while n % d == 0:
                    n //= d
                    e += 1
                ans *= (e + 1)
            d += 1 if d == 2 else 2
        if n > 1:
            ans *= 2
        return ans

    if x <= 0:
        return 0

    k = 0
    n = x
    while n % 2 == 0:
        n //= 2
        k += 1

    if n == 1:
        # Pure powers of two: 1->0, 2->0, 4->0, 8->0, 16->1, ...
        return max(count_divisors(k) - 2, 0)

    return count_divisors(n)
